def wiki_url(title, revid):
    import urllib.parse
    return "https://he.wikipedia.org/w/index.php?title=" + urllib.parse.quote(title.replace(" ", "_")) + f"&oldid={revid}"


def alt(t0, t1, views):
    """camera alternates between the two fronts every 10 s while both are active (the owner 10-23: day 1 looked empty on the Egyptian front because the camera sat on the Golan)"""
    return {"t0": round(t0, 2), "t1": round(t1, 2), "period": 10, "views": [views["sinai"], views["golan"]]}


def articles(used):
    """source.articles for the credit block: the category members whose cards are on the page"""
    return {t: {"revid": r} for k, (t, r) in WIKI.items() if k in used}


