    def wp(key, short):
        t, r = WIKI[key]
        return {"k": key, "u": wiki_url(t, r), "t": f"ויקיפדיה העברית: {t}", "s": f"ויקיפדיה: {short}"}

    def wk(cid, key, short, day, clock, minute, area, unit, title, quote, **kw):
        return card(cid, day, clock, minute, area, unit, title, quote, src=wp(key, short), **kw)

    def place(pid, name, lat, lon, side, article=None, basis=None):
        """article = the Wikipedia article whose own coordinates are used (exact); otherwise basis explains the approximation"""
        PLACES[pid] = pl(name, lat, lon, side, basis, "approximate") if basis else pl(name, lat, lon, side, f"נקודת המקום בערך ״{article}״ בוויקיפדיה העברית")
        P[pid] = [lat, lon]; HIDDEN.add(pid)

