    # ---------------- the sea battles IN the simulation (the owner 10-23: "add to the simulation") ----------------
    # Ships = walk symbols (naval kind from the label), missiles = short arrows, hits = booms, each key event = a mark with its own quote (q + sk) from the battle's article. Times are the article's own
    # clock times; positions are SCHEMATIC (the articles give distances and bearings, not coordinates) and every label says so.
    M = lambda d, h, m: d * 1440 + h * 60 + m
    TT = lambda m: at(m // 1440, m % 1440)               # absolute minute from the war's start -> scene time (with the day gaps)
    SQL = lambda lat, lon: [lat, lon]

    def ship(label, cls, legs):
        return {"type": "walk", "label": label + " (סכמטי)", "cls": cls, "sym": "▣", "area": "sea", "trail": None,
                "legs": [{"t0": TT(a), "t1": TT(b), "path": path} for a, b, path in legs]}

    def shot(m0, m1, frm, to, color, label):
        return {"type": "arrow", "path": [frm, to], "t0": TT(m0), "t1": TT(m1), "label": label + " (סכמטי)", "color": color, "hold": 40, "area": "sea", "trail": "foot"}

    def tag(m, pos, label, q, sk, dur=9, area="sea"):
        return {"type": "mark", "at": pos, "t0": TT(m), "t1": TT(m) + dur, "label": label, "area": area, "q": q, "sk": sk, "s": (f"ויקיפדיה: {WIKI[sk][0]}" if sk in WIKI else "ויקיפדיה: מלחמת יום הכיפורים" if sk == "main" else "המחלקה להיסטוריה בצה״ל, ״יסודות״ 5, עמ׳ 25")}

