    ITEMS += [shot(M(0, 23, 18), M(0, 23, 24), [35.34, 35.1], [35.5, 35.42], BLU, "שני טילי גבריאל של רשף"), boom([35.50, 35.45], TT(M(0, 23, 25)), "sea", 1)]
